package api

import "testing"

func TestBulkCreateRejectsWholeBatchWhenCumulativeExceedsCapacity(t *testing.T) {
	srv := startServer(t)
	defer srv.Close()

	cap := 2
	agent := doRequest(t, srv.URL, "POST", "/api/agents", map[string]any{
		"name": "Ada", "email": "a@example.com", "maxOpenTickets": cap,
	})
	agentID := agent.body["id"]

	resp := doRequest(t, srv.URL, "POST", "/api/tickets/bulk-create", map[string]any{
		"agentId": agentID,
		"tickets": []map[string]any{
			{"subject": "A"},
			{"subject": "B"},
			{"subject": "C"},
		},
	})
	if resp.status != 400 {
		t.Fatalf("expected 400 (batch of 3 exceeds cap 2), got %d", resp.status)
	}

	listed := doRequest(t, srv.URL, "GET", "/api/tickets?agentId="+jsonNum(agentID), nil)
	if len(listed.list) != 0 {
		t.Fatalf("expected no tickets created, got %d", len(listed.list))
	}
}

func TestBulkCreateSucceedsWithinCapacity(t *testing.T) {
	srv := startServer(t)
	defer srv.Close()

	cap := 3
	agent := doRequest(t, srv.URL, "POST", "/api/agents", map[string]any{
		"name": "Ada", "email": "a@example.com", "maxOpenTickets": cap,
	})
	agentID := agent.body["id"]

	resp := doRequest(t, srv.URL, "POST", "/api/tickets/bulk-create", map[string]any{
		"agentId": agentID,
		"tickets": []map[string]any{
			{"subject": "A"},
			{"subject": "B"},
		},
	})
	if resp.status != 201 {
		t.Fatalf("expected 201, got %d", resp.status)
	}
}

